          </div>
        </div>
      )}
    </div>
  );
}

"use client";
import toast from 'react-hot-toast';

import React, { useEffect, useState, useCallback } from "react";
import { useTheme } from "@/providers/theme-provider";
import { invoicesService } from "@/services/invoices.service";
import { InvoiceModal } from "@/components/invoices/InvoiceModal";
import {
  Search, Receipt, Filter, Download, RefreshCw,
  Eye, FileText, AlertCircle, Calendar
} from "lucide-react";

const TYPE_COLORS: Record<string, { bg: string; text: string }> = {
  HOC: { bg: "bg-[#DCFCE7]", text: "text-[#16A34A]" },
  HAC: { bg: "bg-[#EEF1FE]", text: "text-[#3D5EF6]" },
};

function TypeBadge({ type }: { type: string }) {
  const s = TYPE_COLORS[type] || TYPE_COLORS["HOC"];
  return <span className={`text-xs font-bold px-2 py-0.5 rounded-full ${s.bg} ${s.text}`}>{type}</span>;
}

export default function InvoicesPage() {
  const { theme } = useTheme();
  const isDark = theme === "dark";
  const card = `rounded-[16px] p-7 border-0 card-elevated transition-all duration-300 hover:-translate-y-0.5 ${
    isDark
      ? "bg-[#111827] text-white"
      : "bg-white text-[#111827]"
  }`;
  const ht = isDark ? "text-white/90" : "text-[#111827]";
  const mt = isDark ? "text-white/40" : "text-[#9CA3AF]";
  const inputCls = `bg-transparent outline-none w-full text-xs ${isDark ? "text-white" : "text-[#111827]"}`;
  const inputWrap = `flex items-center gap-2 px-3 py-2.5 rounded-[10px] border text-sm ${isDark ? "bg-white/5 border-white/10 text-white/60" : "bg-white border-[#E5E7EB] text-[#6B7280] shadow-sm"}`;
  const selectCls = `px-3 py-2.5 rounded-[10px] border text-xs font-semibold outline-none cursor-pointer ${isDark ? "bg-white/5 border-white/10 text-white" : "bg-white border-[#E5E7EB] text-[#111827] shadow-sm"}`;

  const [loading, setLoading] = useState(true);
  const [invoices, setInvoices] = useState<any[]>([]);
  const [search, setSearch] = useState("");
  const [typeFilter, setTypeFilter] = useState("all");
  const [statusFilter, setStatusFilter] = useState("all");
  const [startDate, setStartDate] = useState("");
  const [endDate, setEndDate] = useState("");

  const [selectedInvoice, setSelectedInvoice] = useState<any>(null);
  const [pdfData, setPdfData] = useState<any>(null);
  const [pdfLoading, setPdfLoading] = useState(false);

  const activeParams = {
    search: search || undefined,
    type: typeFilter !== "all" ? typeFilter : undefined,
    status: statusFilter !== "all" ? statusFilter : undefined,
    startDate: startDate || undefined,
    endDate: endDate || undefined,
  };

  const fetchInvoices = useCallback(async () => {
    try {
      setLoading(true);
      const data = await invoicesService.getInvoices(activeParams);
      setInvoices(data);
    } catch (err) {
      console.error("Failed to load invoices:", err);
    } finally {
      setLoading(false);
    }
  }, [search, typeFilter, statusFilter, startDate, endDate]);

  useEffect(() => {
    let isSubscribed = true;
    (async () => {
      if (isSubscribed) {
        await fetchInvoices();
      }
    })();
    return () => { isSubscribed = false; };
  }, [fetchInvoices]);

  const openPdf = async (inv: any) => {
    setSelectedInvoice(inv);
    setPdfLoading(true);
    try {
      const data = await invoicesService.getInvoicePdfData(inv.id);
      setPdfData(data);
    } catch (err) {
      console.error("Failed to load invoice PDF data:", err);
      setPdfData(null);
    } finally {
      setPdfLoading(false);
    }
  };

  const exportCSV = async () => {
    try {
      const rows = await invoicesService.exportInvoices(activeParams);
      if (!rows || rows.length === 0) { toast("No records to export."); return; }
      const headers = Object.keys(rows[0]);
      const csv = [
        headers.join(","),
        ...rows.map((r: any) => headers.map(h => `"${String(r[h] ?? "").replace(/"/g, '""')}"`).join(","))
      ].join("\n");
      const blob = new Blob([csv], { type: "text/csv" });
      const url = URL.createObjectURL(blob);
      const a = document.createElement("a"); a.href = url; a.download = `invoices-export-${Date.now()}.csv`; a.click();
      URL.revokeObjectURL(url);
    } catch (err) {
      console.error("Export failed:", err);
    }
  };

  const stats = {
    total: invoices.length,
    hoc: invoices.filter(i => i.invoice_type === "HOC").length,
    hac: invoices.filter(i => i.invoice_type === "HAC").length,
    totalAmount: invoices.reduce((sum, i) => sum + (parseFloat(i.final_amount) || 0), 0),
  };

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-4">
        <div>
          <h1 className={`text-2xl font-bold tracking-tight ${ht}`}>Invoice Management</h1>
          <p className={`text-xs mt-1.5 ${mt}`}>View and manage all HOC & HAC invoices. Read-only access.</p>
        </div>
        <div className="flex gap-2">
          <button onClick={exportCSV} className={`flex items-center gap-2 text-sm font-semibold px-4 py-2 rounded-xl transition-colors ${isDark ? "bg-white/8 hover:bg-white/12 text-white/70" : "bg-slate-100 hover:bg-slate-200 text-slate-700"}`}>
            <Download className="w-4 h-4" />
            Export CSV
          </button>
          <button onClick={fetchInvoices} className={`p-2.5 rounded-xl transition-colors ${isDark ? "bg-white/5 hover:bg-white/10 text-white/50" : "bg-slate-100 hover:bg-slate-200 text-slate-500"}`}>
            <RefreshCw className="w-4 h-4" />
          </button>
        </div>
      </div>

      {/* Stats */}
      <div className="grid grid-cols-2 sm:grid-cols-4 gap-4">
        {[
          { label: "Total Invoices", value: stats.total, icon: Receipt, color: "text-blue-500" },
          { label: "HOC (Direct)", value: stats.hoc, icon: FileText, color: "text-emerald-500" },
          { label: "HAC (Agent Referred)", value: stats.hac, icon: FileText, color: "text-indigo-500" },
          { label: "Total Revenue", value: `₹${stats.totalAmount.toLocaleString("en-IN")}`, icon: Receipt, color: "text-purple-500" },
        ].map((s, i) => (
          <div key={i} className={`${card} flex items-center gap-4`}>
            <div className={`w-10 h-10 rounded-xl flex items-center justify-center ${s.color}`}>
              <s.icon className="w-5 h-5" />
            </div>
            <div>
              <div className={`text-xs ${mt}`}>{s.label}</div>
              <div className={`text-xl font-bold ${ht}`}>{s.value}</div>
            </div>
          </div>
        ))}
      </div>

      {/* Search & Filters */}
      <div className="flex flex-col md:flex-row gap-3 flex-wrap">
        <label className={`${inputWrap} flex-1 min-w-[200px]`}>
          <Search className="w-4 h-4 opacity-55" />
          <input className={inputCls} value={search} onChange={e => setSearch(e.target.value)} placeholder="Search by Invoice #, Seafarer Name, or Transaction ID..." />
        </label>
        <select className={selectCls} value={typeFilter} onChange={e => setTypeFilter(e.target.value)}>
          <option value="all">All Types</option>
          <option value="HOC">HOC (Direct)</option>
          <option value="HAC">HAC (Agent Referred)</option>
        </select>
        <select className={selectCls} value={statusFilter} onChange={e => setStatusFilter(e.target.value)}>
          <option value="all">All Statuses</option>
          <option value="Paid">Paid</option>
          <option value="Processing">Processing</option>
          <option value="Cancelled">Cancelled</option>
        </select>
        <div className={`${inputWrap} gap-2`}>
          <Calendar className="w-4 h-4 opacity-55 flex-shrink-0" />
          <input type="date" className={inputCls} value={startDate} onChange={e => setStartDate(e.target.value)} />
          <span className={`text-xs ${mt}`}>to</span>
          <input type="date" className={inputCls} value={endDate} onChange={e => setEndDate(e.target.value)} />
        </div>
      </div>

      {/* Invoice Table */}
      <div className={`${card} overflow-hidden p-0`}>
        <div className="overflow-x-auto">
          <table className="w-full text-xs">
            <thead>
              <tr className={`border-b text-[11px] ${isDark ? "border-white/10 bg-white/[0.02]" : "border-slate-100 bg-slate-50"}`}>
                {[
                  "Invoice Number",
                  "Invoice Date",
                  "Seafarer",
                  "Course",
                  "Institute",
                  "Hari Om Payable",
                  "Payment Status",
                  "Invoice Status",
                  "Actions",
                ].map((h, i) => (
                  <th
                    key={h}
                    className={`py-3 font-semibold ${mt} whitespace-nowrap ${
                      i === 0 ? "pl-5 pr-2.5 text-left" : i === 8 ? "pl-2.5 pr-5 text-right" : "px-2.5 text-left"
                    }`}
                  >
                    {h}
                  </th>
                ))}
              </tr>
            </thead>
            <tbody>
              {loading ? (
                Array.from({ length: 6 }).map((_, i) => (
                  <tr key={i} className={`border-b ${isDark ? "border-white/5" : "border-slate-50"}`}>
                    {Array.from({ length: 9 }).map((_, j) => (
                      <td key={j} className={`py-3 ${j === 0 ? "pl-5 pr-2.5" : j === 8 ? "pl-2.5 pr-5" : "px-2.5"}`}>
                        <div className={`h-3 rounded-full animate-pulse ${isDark ? "bg-white/10" : "bg-slate-200"}`} style={{ width: `${[60, 45, 75, 50, 65, 80, 55, 70, 40, 60][(i + j) % 10]}%` }} />
                      </td>
                    ))}
                  </tr>
                ))
              ) : invoices.length === 0 ? (
                <tr>
                  <td colSpan={9} className="px-5 py-12 text-center">
                    <AlertCircle className={`w-8 h-8 mx-auto mb-2 ${mt}`} />
                    <div className={`text-sm font-semibold ${mt}`}>No partner invoices found</div>
                    <div className={`text-xs mt-1 ${mt}`}>Invoices associated with Seafarers handled through this Partner will appear here.</div>
                  </td>
                </tr>
              ) : invoices.map((inv: any) => (
                <tr key={inv.id} className={`border-b ${isDark ? "border-white/5 hover:bg-white/[0.025]" : "border-slate-50 hover:bg-slate-50/60"} transition-colors`}>
                  {/* Invoice Number */}
                  <td className="pl-5 pr-2.5 py-3.5 font-mono font-bold text-[#3D5EF6] text-xs whitespace-nowrap">
                    {inv.invoice_number}
                  </td>

                  {/* Invoice Date */}
                  <td className="px-2.5 py-3.5 whitespace-nowrap text-[11px] font-medium">
                    {inv.payment_date ? new Date(inv.payment_date).toLocaleDateString("en-IN", { day: "numeric", month: "short", year: "numeric" }) : "—"}
                  </td>

                  {/* Seafarer */}
                  <td className="px-2.5 py-3.5 max-w-[150px]">
                    <div className={`font-bold text-xs truncate ${ht}`}>{inv.customer_name}</div>
                    <div className={`text-[10px] truncate ${mt}`}>{inv.customer_email}</div>
                  </td>

                  {/* Course */}
                  <td className="px-2.5 py-3.5 max-w-[160px]">
                    <div className={`truncate font-semibold text-xs ${isDark ? "text-white/80" : "text-[#111827]"}`} title={inv.course_name}>
                      {inv.course_name}
                    </div>
                  </td>

                  {/* Institute */}
                  <td className="px-2.5 py-3.5 max-w-[150px]">
                    <div className={`truncate text-xs ${mt}`} title={inv.institute_name || "Hari Om Maritime Institute, Mumbai"}>
                      {inv.institute_name || "Hari Om Maritime Institute"}
                    </div>
                  </td>

                  {/* Amount Applicable to Hari Om */}
                  <td className="px-2.5 py-3.5 font-mono font-bold text-xs text-[#16A34A] whitespace-nowrap">
                    ₹{(inv.hariom_payable_amount ?? inv.final_amount ?? 0).toLocaleString("en-IN")}
                  </td>

                  {/* Payment Status */}
                  <td className="px-2.5 py-3.5 whitespace-nowrap">
                    <span className={`text-[10px] font-bold px-2.5 py-1 rounded-full ${
                      (inv.payment_status || inv.status) === "Paid"
                        ? "bg-[#DCFCE7] text-[#16A34A]"
                        : "bg-[#FEF3C7] text-[#B45309]"
                    }`}>
                      {inv.payment_status || inv.status || "Paid"}
                    </span>
                  </td>

                  {/* Invoice Status */}
                  <td className="px-2.5 py-3.5 whitespace-nowrap">
                    <span className={`text-[10px] font-bold px-2.5 py-1 rounded-full ${
                      (inv.invoice_status || "Issued") === "Issued"
                        ? "bg-[#EEF1FE] text-[#3D5EF6]"
                        : "bg-slate-100 text-[#6B7280]"
                    }`}>
                      {inv.invoice_status || "Issued"}
                    </span>
                  </td>

                  {/* Actions */}
                  <td className="pl-2.5 pr-5 py-3.5 text-right whitespace-nowrap">
                    <button
                      onClick={() => openPdf(inv)}
                      className="text-xs font-semibold px-3 py-1.5 rounded-xl bg-[#3D5EF6] hover:bg-[#2E4FE0] text-white transition-colors cursor-pointer flex items-center gap-1.5 ml-auto shadow-sm"
                    >
                      <FileText className="w-3.5 h-3.5" />
                      View Invoice
                    </button>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>

      {/* PDF Modal */}
      {selectedInvoice && (
        pdfLoading ? (
          <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/60 backdrop-blur-sm">
            <div className="bg-white dark:bg-[#111827] rounded-[16px] card-elevated border-0 p-8 text-center shadow-2xl">
              <div className="w-8 h-8 border-4 border-[#3D5EF6] border-t-transparent rounded-full animate-spin mx-auto mb-3" />
              <div className={`text-sm ${ht}`}>Loading invoice...</div>
            </div>
          </div>
        ) : pdfData ? (
          <InvoiceModal pdfData={pdfData} onClose={() => { setSelectedInvoice(null); setPdfData(null); }} />
        ) : (
          <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/60 backdrop-blur-sm p-4">
            <div className="bg-white dark:bg-[#111827] rounded-[16px] card-elevated border-0 p-8 text-center shadow-2xl max-w-sm w-full">
              <AlertCircle className="w-10 h-10 text-[#DC2626] mx-auto mb-3" />
              <div className={`text-sm font-semibold mb-1 ${ht}`}>Failed to load invoice</div>
              <div className={`text-xs ${mt} mb-4`}>Could not retrieve invoice PDF data. Please try again.</div>
              <button onClick={() => setSelectedInvoice(null)} className="text-xs font-semibold px-4 py-2 rounded-[10px] bg-slate-100 dark:bg-white/5 hover:bg-slate-200 text-[#111827] dark:text-white">Close</button>
            </div>
          </div>
        )
      )}
    </div>
  );
}

"use client";

import React, { useEffect, useState } from "react";
import AgentAdminSidebar from "@/components/agent-admin/sidebar";
import AgentAdminTopbar from "@/components/agent-admin/topbar";
import { useTheme } from "@/providers/theme-provider";

export default function AgentAdminLayout({
  children,
}: {
  children: React.ReactNode;
}) {
  const { theme, mounted } = useTheme();
  const isDark = theme === "dark";

  const themeClasses = mounted && !isDark ? "bg-[#FAFAFA] text-[#111827]" : "bg-[#050a14] text-white";
  const isDarkActive = mounted ? isDark : true;

  return (
    <div className={`flex h-screen relative overflow-hidden font-outfit ${themeClasses}`}>
      {/* Decorative Background Elements */}
      <div className={`absolute top-0 right-0 w-[800px] h-[800px] rounded-full blur-[120px] pointer-events-none transition-all duration-1000 ${
        isDarkActive ? "bg-[#3D5EF6]/10" : "bg-[#3D5EF6]/5"
      }`} />
      <div className={`absolute bottom-0 left-0 w-[600px] h-[600px] rounded-full blur-[100px] pointer-events-none transition-all duration-1000 ${
        isDarkActive ? "bg-[#3D5EF6]/10" : "bg-[#3D5EF6]/5"
      }`} />

      {/* Sidebar */}
      <AgentAdminSidebar />

      {/* Main Content */}
      <div className="flex-1 flex flex-col overflow-hidden relative z-10">
        {/* Topbar */}
        <AgentAdminTopbar />

        {/* Page Content */}
        <main className="flex-1 overflow-y-auto custom-scrollbar">
          <div className="p-6 w-full max-w-7xl">{children}</div>
        </main>
      </div>
    </div>
  );
}

"use client";

import React, { useEffect, useState } from "react";
import { useTheme } from "@/providers/theme-provider";
import {
  partnerPricingService,
  CoursePricingItem,
} from "@/services/partner-pricing.service";
import {
  Tag,
  Search,
  CheckCircle2,
  Clock,
  AlertCircle,
  Edit3,
  Send,
  X,
  Info,
  Building2,
  ArrowRight,
  RefreshCw,
} from "lucide-react";

export default function PartnerCoursePricingPage() {
  const { theme } = useTheme();
  const isDark = theme === "dark";

  const [pricings, setPricings] = useState<CoursePricingItem[]>([]);
  const [loading, setLoading] = useState(true);
  const [search, setSearch] = useState("");
  const [statusFilter, setStatusFilter] = useState("all");

  // Modal State
  const [selectedCourse, setSelectedCourse] = useState<CoursePricingItem | null>(null);
  const [proposedAmount, setProposedAmount] = useState<string>("");
  const [submitting, setSubmitting] = useState(false);
  const [successMsg, setSuccessMsg] = useState<string | null>(null);
  const [errorMsg, setErrorMsg] = useState<string | null>(null);

  const fetchPricings = async () => {
    setLoading(true);
    try {
      const data = await partnerPricingService.getCoursePricings();
      setPricings(data);
    } catch (err) {
      console.error("Failed to load course pricings:", err);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    let isSubscribed = true;
    (async () => {
      if (isSubscribed) {
        await fetchPricings();
      }
    })();
    return () => { isSubscribed = false; };
  }, []);

  const openProposeModal = (item: CoursePricingItem) => {
    setSelectedCourse(item);
    setProposedAmount(
      item.proposedPayableAmount
        ? item.proposedPayableAmount.toString()
        : item.activePayableAmount.toString()
    );
    setErrorMsg(null);
    setSuccessMsg(null);
  };

  const handleProposeSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!selectedCourse) return;

    const val = parseFloat(proposedAmount);
    if (isNaN(val) || val <= 0) {
      setErrorMsg("Please enter a valid positive Hari Om payable amount.");
      return;
    }

    setSubmitting(true);
    setErrorMsg(null);
    try {
      await partnerPricingService.submitProposedPrice(selectedCourse.id, val);
      setSuccessMsg(`Proposed price of ₹${val.toLocaleString("en-IN")} submitted for Master Admin approval.`);
      setTimeout(() => {
        setSelectedCourse(null);
        fetchPricings();
      }, 1200);
    } catch (err) {
      setErrorMsg("Failed to submit pricing change request. Please try again.");
    } finally {
      setSubmitting(false);
    }
  };

  const filteredPricings = pricings.filter((item) => {
    const matchesSearch =
      item.courseName.toLowerCase().includes(search.toLowerCase()) ||
      item.courseCode.toLowerCase().includes(search.toLowerCase()) ||
      item.category.toLowerCase().includes(search.toLowerCase());

    if (statusFilter === "all") return matchesSearch;
    if (statusFilter === "active") return matchesSearch && item.status === "Active";
    if (statusFilter === "pending") return matchesSearch && item.status === "Pending Approval";
    if (statusFilter === "rejected") return matchesSearch && item.status === "Rejected";
    return matchesSearch;
  });

  // UI Tokens
  const bgCard = isDark
    ? "bg-[#111827] border-0 card-elevated"
    : "bg-white border-0 card-elevated";
  const ht = isDark ? "text-white/90" : "text-[#111827]";
  const mt = isDark ? "text-white/40" : "text-[#9CA3AF]";
  const inputCls = isDark
    ? "bg-white/5 border-white/10 text-white placeholder:text-white/20 focus:border-[#3D5EF6]"
    : "bg-[#FAFAFA] border-[#E5E7EB] text-[#111827] placeholder:text-[#9CA3AF] focus:border-[#3D5EF6]";

  return (
    <div className="space-y-6">
      {/* Page Header */}
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
          <div className="flex items-center gap-2">
            <div className="w-8 h-8 rounded-xl bg-[#3D5EF6]/15 flex items-center justify-center text-[#3D5EF6]">
              <Tag className="w-4 h-4" />
            </div>
            <h1 className={`text-2xl font-extrabold tracking-tight ${ht}`}>
              Partner Course Pricing
            </h1>
          </div>
          <p className={`text-xs mt-1.5 ${mt}`}>
            View applicable courses and manage your proposed Hari Om payable amounts.
          </p>
        </div>

        <button
          onClick={fetchPricings}
          className={`flex items-center gap-2 px-3.5 py-2 rounded-xl text-xs font-semibold border transition-all ${
            isDark
              ? "bg-white/5 border-white/10 hover:bg-white/10 text-white/80"
              : "bg-slate-100 border-slate-200 hover:bg-slate-200 text-slate-700"
          }`}
        >
          <RefreshCw className={`w-3.5 h-3.5 ${loading ? "animate-spin" : ""}`} />
          Refresh Pricing
        </button>
      </div>



      {/* Status Summary KPI Strip (PRD Section 4.7) */}
      <div className="grid grid-cols-1 sm:grid-cols-3 gap-6">
        <div className={`p-6 rounded-[16px] ${bgCard} flex items-center justify-between`}>
          <div>
            <p className="text-[10px] font-bold uppercase tracking-wider text-[#9CA3AF]">Active Prices</p>
            <p className={`text-3xl font-black mt-2 text-emerald-500 leading-none`}>
              {pricings.filter((x) => x.status === "Active").length}
            </p>
            <p className={`text-[10px] mt-2 font-medium ${mt}`}>Currently in effect for purchases</p>
          </div>
          <div className="w-11 h-11 rounded-full bg-emerald-500/10 flex items-center justify-center text-emerald-500 shrink-0">
            <CheckCircle2 className="w-5 h-5" />
          </div>
        </div>

        <div className={`p-6 rounded-[16px] ${bgCard} flex items-center justify-between`}>
          <div>
            <p className="text-[10px] font-bold uppercase tracking-wider text-[#9CA3AF]">Pending Approval</p>
            <p className={`text-3xl font-black mt-2 ${ht} leading-none`}>
              {pricings.filter((x) => x.status === "Pending Approval").length}
            </p>
            <p className={`text-[10px] mt-2 font-medium ${mt}`}>Awaiting Master Admin review</p>
          </div>
          <div className="w-11 h-11 rounded-full bg-slate-100 dark:bg-white/5 flex items-center justify-center text-slate-500 dark:text-slate-400 shrink-0">
            <Clock className="w-5 h-5" />
          </div>
        </div>

        <div className={`p-6 rounded-[16px] ${bgCard} flex items-center justify-between`}>
          <div>
            <p className="text-[10px] font-bold uppercase tracking-wider text-[#9CA3AF]">Rejected Proposals</p>
            <p className={`text-3xl font-black mt-2 text-red-500 leading-none`}>
              {pricings.filter((x) => x.status === "Rejected").length}
            </p>
            <p className={`text-[10px] mt-2 font-medium ${mt}`}>Active price kept unchanged</p>
          </div>
          <div className="w-11 h-11 rounded-full bg-red-500/10 flex items-center justify-center text-red-500 shrink-0">
            <AlertCircle className="w-5 h-5" />
          </div>
        </div>
      </div>

      {/* Filter & Search Bar */}
      <div className={`p-4 rounded-lg ${bgCard} flex flex-col sm:flex-row items-center justify-between gap-3`}>
        <div className="relative w-full sm:w-72">
          <Search className={`absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 ${mt}`} />
          <input
            type="text"
            placeholder="Search courses by name or code..."
            value={search}
            onChange={(e) => setSearch(e.target.value)}
            className={`w-full pl-9 pr-4 py-2 text-xs rounded-lg outline-none border transition-all ${inputCls}`}
          />
        </div>

        <div className="flex items-center gap-1.5 w-full sm:w-auto overflow-x-auto pb-1 sm:pb-0">
          {[
            { id: "all", label: "All Courses" },
            { id: "active", label: "Active" },
            { id: "pending", label: "Pending Approval" },
            { id: "rejected", label: "Rejected" },
          ].map((tab) => (
            <button
              key={tab.id}
              onClick={() => setStatusFilter(tab.id)}
              className={`px-3 py-1.5 rounded-lg text-xs font-semibold whitespace-nowrap transition-all ${
                statusFilter === tab.id
                  ? "bg-[#3D5EF6] text-white shadow-md"
                  : isDark
                  ? "bg-white/5 text-white/50 hover:bg-white/10 hover:text-white"
                  : "bg-slate-100 text-slate-600 hover:bg-slate-200"
              }`}
            >
              {tab.label}
            </button>
          ))}
        </div>
      </div>

      {/* Course Cards Grid */}
      {loading ? (
        <div className="flex h-48 items-center justify-center">
          <div className="w-8 h-8 border-4 border-[#3D5EF6] border-t-transparent rounded-full animate-spin" />
        </div>
      ) : filteredPricings.length === 0 ? (
        <div className={`p-12 text-center rounded-lg ${bgCard}`}>
          <Tag className={`w-10 h-10 mx-auto opacity-30 ${mt}`} />
          <p className={`text-sm font-semibold mt-3 ${ht}`}>No matching course pricing records found</p>
          <p className={`text-xs mt-1 ${mt}`}>Try resetting your search query or filters.</p>
        </div>
      ) : (
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-5">
          {filteredPricings.map((item) => {
            const isPending = item.status === "Pending Approval";
            const isRejected = item.status === "Rejected";

            return (
              <div
                key={item.id}
                className={`p-6 rounded-[16px] ${bgCard} flex flex-col justify-between transition-all duration-300 hover:-translate-y-0.5`}
              >
                <div>
                  {/* Top Badge & Code */}
                  <div className="flex items-center justify-between gap-2 mb-3">
                    <span className="px-3 py-0.5 rounded-full text-[10px] font-mono font-bold bg-[#3D5EF6]/10 text-[#3D5EF6]">
                      {item.courseCode}
                    </span>

                    {/* Status Badge (PRD 4.7) */}
                    {isPending ? (
                      <span className="flex items-center gap-1.5 px-3 py-0.5 rounded-full text-[10px] font-bold bg-[#FEF3C7] text-[#B45309]">
                        <Clock className="w-3 h-3 text-[#B45309]" /> Pending Approval
                      </span>
                    ) : isRejected ? (
                      <span className="flex items-center gap-1.5 px-3 py-0.5 rounded-full text-[10px] font-bold bg-[#FEE2E2] text-[#DC2626]">
                        <AlertCircle className="w-3 h-3" /> Proposal Rejected
                      </span>
                    ) : (
                      <span className="flex items-center gap-1.5 px-3 py-0.5 rounded-full text-[10px] font-bold bg-[#DCFCE7] text-[#16A34A]">
                        <CheckCircle2 className="w-3 h-3" /> Active (In Use)
                      </span>
                    )}
                  </div>

                  {/* Course Title */}
                  <h3 className={`text-base font-extrabold leading-snug ${ht}`}>
                    {item.courseName}
                  </h3>
                  <p className={`text-[11px] mt-1 font-medium ${mt}`}>{item.category}</p>

                  {/* Pricing Details */}
                  <div className="mt-5 p-4 rounded-[12px] bg-slate-50/70 dark:bg-white/[0.03] space-y-2.5">
                    <div className="flex items-center justify-between text-xs">
                      <span className={mt}>Public Standard Fee</span>
                      <span className="font-semibold line-through opacity-60">
                        ₹{item.standardFee.toLocaleString("en-IN")}
                      </span>
                    </div>

                    <div className="flex items-center justify-between text-xs">
                      <span className={`font-semibold ${ht}`}>Currently Active Payable</span>
                      <span className="text-base font-extrabold text-[#3D5EF6]">
                        ₹{item.activePayableAmount.toLocaleString("en-IN")}
                      </span>
                    </div>

                    {/* Proposed price box if pending (PRD 4.7 Distinction) */}
                    {isPending && item.proposedPayableAmount && (
                      <div className="pt-2.5 border-t border-slate-200/50 dark:border-white/10 space-y-1.5">
                        <div className="flex items-center justify-between text-xs">
                          <div className="flex items-center gap-1.5">
                            <span className="w-1.5 h-1.5 rounded-full bg-[#9CA3AF] dark:bg-slate-500 shrink-0" />
                            <span className={`font-medium ${ht}`}>
                              Awaiting Master Approval:
                            </span>
                          </div>
                          <span className={`text-sm font-bold ${ht}`}>
                            ₹{item.proposedPayableAmount.toLocaleString("en-IN")}
                          </span>
                        </div>
                        <p className={`text-[10px] leading-tight ${mt}`}>
                          Active price (₹{item.activePayableAmount.toLocaleString("en-IN")}) remains in effect until Master approves.
                        </p>
                      </div>
                    )}

                    {/* Rejection Note */}
                    {isRejected && item.rejectionReason && (
                      <div className="pt-2 border-t border-slate-200/50 dark:border-white/10 text-[11px] text-red-400 leading-tight space-y-1">
                        <p className="font-bold">Rejection Reason:</p>
                        <p className="opacity-90">{item.rejectionReason}</p>
                        <p className="text-[10px] text-slate-400 pt-0.5">
                          Active price (₹{item.activePayableAmount.toLocaleString("en-IN")}) remains in effect.
                        </p>
                      </div>
                    )}
                  </div>
                </div>

                {/* Card Footer Action */}
                <div className="mt-5 pt-3 border-t border-slate-100 dark:border-white/5 flex items-center justify-between">
                  <span className={`text-[10px] ${mt}`}>
                    Updated {new Date(item.lastUpdated).toLocaleDateString("en-IN")}
                  </span>

                  <button
                    onClick={() => openProposeModal(item)}
                    disabled={isPending}
                    className={`px-4 py-2 rounded-full text-xs font-semibold transition-all ${
                      isPending
                        ? "bg-amber-500/10 text-amber-500 dark:text-amber-400 border border-amber-500/20 opacity-80 cursor-not-allowed"
                        : "bg-[#3D5EF6] hover:bg-[#2E4FE0] text-white shadow-md active:scale-95 cursor-pointer"
                    }`}
                  >
                    {isPending ? "Under Review" : isRejected ? "Re-propose Price" : "Propose Price"}
                  </button>
                </div>
              </div>
            );
          })}
        </div>
      )}

      {/* Propose Price Modal */}
      {selectedCourse && (
        <div
          className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/60 backdrop-blur-md"
          onClick={() => setSelectedCourse(null)}
        >
          <div
            className={`w-full max-w-lg rounded-[16px] p-7 card-elevated border-0 relative ${
              isDark ? "bg-[#111827] text-white" : "bg-white text-[#111827]"
            }`}
            onClick={(e) => e.stopPropagation()}
          >
            {/* Header */}
            <div className="flex items-center justify-between border-b pb-4 mb-4 border-white/10">
              <div className="flex items-center gap-2.5">
                <div className="w-9 h-9 rounded-full bg-[#3D5EF6]/15 flex items-center justify-center text-[#3D5EF6]">
                  <Tag className="w-4 h-4" />
                </div>
                <div>
                  <h3 className="text-base font-bold">Propose Hari Om Payable Price</h3>
                  <p className={`text-[11px] ${mt}`}>
                    {selectedCourse.courseCode} — {selectedCourse.courseName}
                  </p>
                </div>
              </div>

              <button
                onClick={() => setSelectedCourse(null)}
                className={`p-1.5 rounded-full ${isDark ? "hover:bg-white/10 text-white/60" : "hover:bg-slate-100 text-slate-500"}`}
              >
                <X className="w-4 h-4" />
              </button>
            </div>

            {/* Success / Error Alerts */}
            {successMsg && (
              <div className="mb-4 p-3 rounded-full bg-emerald-500/15 border border-emerald-500/30 text-emerald-400 text-xs font-semibold flex items-center gap-2 px-4">
                <CheckCircle2 className="w-4 h-4 shrink-0" />
                {successMsg}
              </div>
            )}

            {errorMsg && (
              <div className="mb-4 p-3 rounded-full bg-red-500/15 border border-red-500/30 text-red-400 text-xs font-semibold flex items-center gap-2 px-4">
                <AlertCircle className="w-4 h-4 shrink-0" />
                {errorMsg}
              </div>
            )}

            {/* Modal Form */}
            <form onSubmit={handleProposeSubmit} className="space-y-4">
              <div className="p-4 rounded-[12px] bg-slate-50 dark:bg-white/5 border-0 space-y-2 text-xs">
                <div className="flex items-center justify-between">
                  <span className={mt}>Standard Course Fee</span>
                  <span className="font-bold">₹{selectedCourse.standardFee.toLocaleString("en-IN")}</span>
                </div>
                <div className="flex items-center justify-between">
                  <span className={mt}>Current Active Payable Amount</span>
                  <span className="font-bold text-[#3D5EF6]">₹{selectedCourse.activePayableAmount.toLocaleString("en-IN")}</span>
                </div>
              </div>

              <div>
                <label className="block text-xs font-semibold mb-1.5">
                  Proposed Hari Om Payable Amount (₹) <span className="text-red-400">*</span>
                </label>
                <input
                  type="number"
                  required
                  min="1"
                  step="100"
                  value={proposedAmount}
                  onChange={(e) => setProposedAmount(e.target.value)}
                  placeholder="e.g. 11500"
                  className={`w-full px-4 py-2.5 text-sm font-semibold rounded-full outline-none border-0 bg-slate-100 dark:bg-white/5 transition-all ${inputCls}`}
                />
                <p className={`text-[10px] mt-1.5 ${mt}`}>
                  This amount represents what Hari Om is entitled to receive per seafarer booking.
                </p>
              </div>

              {/* Comparison Preview */}
              {parseFloat(proposedAmount) > 0 && (
                <div className="p-3 px-4 rounded-full bg-[#3D5EF6]/10 text-xs flex items-center justify-between text-[#3D5EF6]">
                  <span>Price Change Comparison:</span>
                  <div className="flex items-center gap-2 font-bold">
                    <span className="line-through opacity-70">₹{selectedCourse.activePayableAmount.toLocaleString("en-IN")}</span>
                    <ArrowRight className="w-3.5 h-3.5" />
                    <span className="text-[#3D5EF6] text-sm">₹{parseFloat(proposedAmount).toLocaleString("en-IN")}</span>
                  </div>
                </div>
              )}

              {/* Actions */}
              <div className="pt-3 flex items-center justify-end gap-3 border-t border-slate-100 dark:border-white/10">
                <button
                  type="button"
                  onClick={() => setSelectedCourse(null)}
                  className={`px-5 py-2 text-xs font-semibold rounded-full ${
                    isDark ? "hover:bg-white/10 text-white/70" : "hover:bg-slate-100 text-slate-600"
                  }`}
                >
                  Cancel
                </button>

                <button
                  type="submit"
                  disabled={submitting}
                  className="px-6 py-2.5 text-xs font-bold text-white rounded-full bg-[#3D5EF6] hover:bg-[#2E4FE0] transition-all shadow-md active:scale-95 disabled:opacity-50 cursor-pointer"
                >
                  {submitting ? "Submitting..." : "Submit for Approval"}
                </button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
}

"use client";

import React, { useState } from "react";
import { useTheme } from "@/providers/theme-provider";
import { useAuth } from "@/providers/auth-provider";
import { User, ShieldCheck, Mail, Phone, Lock, Check } from "lucide-react";

export default function Profile() {
  const { theme } = useTheme();
  const isDark = theme === "dark";
  const { user, updateSecurity } = useAuth();

  const [currentPassword, setCurrentPassword] = useState("");
  const [newPassword, setNewPassword] = useState("");
  const [confirmPassword, setConfirmPassword] = useState("");
  const [error, setError] = useState("");
  const [success, setSuccess] = useState(false);
  const [loading, setLoading] = useState(false);

  const card = `rounded-[16px] p-7 border-0 card-elevated transition-all duration-300 hover:-translate-y-0.5 ${
    isDark
      ? "bg-[#111827] text-white"
      : "bg-white text-[#111827]"
  }`;
  const inputBg = isDark ? "bg-white/5 border-white/10 text-white placeholder:text-white/20" : "bg-[#FAFAFA] border-[#E5E7EB] text-[#111827] placeholder:text-[#9CA3AF]";
  const labelText = isDark ? "text-white/50" : "text-[#6B7280]";
  const ht = isDark ? "text-white/95" : "text-[#111827]";
  const mt = isDark ? "text-white/35" : "text-[#9CA3AF]";

  const handleUpdatePassword = async (e: React.FormEvent) => {
    e.preventDefault();
    setError("");
    setSuccess(false);

    if (newPassword !== confirmPassword) {
      setError("New password and confirmation do not match.");
      return;
    }

    setLoading(true);
    try {
      await updateSecurity({
        currentPassword,
        newPassword,
      });
      setSuccess(true);
      setCurrentPassword("");
      setNewPassword("");
      setConfirmPassword("");
    } catch (err: any) {
      setError(err.message || "Failed to update security credentials.");
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="space-y-6">
      {/* Header */}
      <div>
        <h1 className={`text-2xl font-bold tracking-tight ${ht}`}>Account Settings</h1>
        <p className={`text-xs mt-1.5 ${mt}`}>Manage your personal credentials, contact info, and security parameters.</p>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">

        {/* Profile Card */}
        <div className={`${card} h-fit space-y-6`}>
          <div className="flex flex-col items-center text-center">
            <div className="w-16 h-16 rounded-full bg-[#3D5EF6] flex items-center justify-center text-white text-xl font-black uppercase shadow-lg mb-4">
              {user?.name ? user.name.split(" ").map((n: any) => n[0]).join("") : "AA"}
            </div>
            <h3 className={`text-sm font-bold ${ht}`}>{user?.name || "Agent Admin"}</h3>
            <span className="px-2.5 py-0.5 rounded-full text-[10px] font-bold bg-[#3D5EF6]/10 text-[#3D5EF6] mt-2 flex items-center gap-1.5">
              <ShieldCheck className="w-3.5 h-3.5" />
              {user?.role || "AGENT_ADMIN"}
            </span>
          </div>

          <div className="space-y-4 pt-4 border-t border-white/5 text-xs">
            <div className="flex items-center gap-3">
              <Mail className="w-4 h-4 text-[#3D5EF6] shrink-0" />
              <div className="min-w-0">
                <p className={labelText}>Email Address</p>
                <p className={`font-semibold truncate ${ht}`}>{user?.email || "admin@thalassic.in"}</p>
              </div>
            </div>

            <div className="flex items-center gap-3">
              <Phone className="w-4 h-4 text-[#3D5EF6] shrink-0" />
              <div className="min-w-0">
                <p className={labelText}>Contact Number</p>
                <p className={`font-semibold truncate ${ht}`}>{user?.phone || "+91 99887 76655"}</p>
              </div>
            </div>
          </div>
        </div>

        {/* Change Password Form */}
        <div className={`${card} lg:col-span-2 space-y-6 self-start max-w-2xl`}>
          <div className="flex items-center gap-2 border-b pb-4 mb-4 border-white/5">
            <Lock className="w-4 h-4 text-[#3D5EF6]" />
            <h3 className="text-sm font-bold">Change Password</h3>
          </div>

          {error && <p className="text-xs text-[#DC2626] bg-[#FEE2E2] p-2 rounded-[10px] font-semibold">{error}</p>}
          {success && <p className="text-xs text-[#16A34A] bg-[#DCFCE7] p-2 rounded-[10px] font-semibold flex items-center gap-1"><Check className="w-4 h-4" /> Password updated successfully!</p>}

          <form onSubmit={handleUpdatePassword} className="space-y-4 max-w-sm">
            <div className="space-y-1">
              <label className={`text-[10px] font-bold ${labelText}`}>Current Password</label>
              <input
                type="password"
                required
                value={currentPassword}
                onChange={(e) => setCurrentPassword(e.target.value)}
                placeholder="••••••••"
                className={`w-full px-3 py-2.5 rounded-xl border text-xs outline-none ${inputBg}`}
              />
            </div>

            <div className="space-y-1">
              <label className={`text-[10px] font-bold ${labelText}`}>New Password</label>
              <input
                type="password"
                required
                value={newPassword}
                onChange={(e) => setNewPassword(e.target.value)}
                placeholder="••••••••"
                className={`w-full px-3 py-2.5 rounded-xl border text-xs outline-none ${inputBg}`}
              />
            </div>

            <div className="space-y-1">
              <label className={`text-[10px] font-bold ${labelText}`}>Confirm New Password</label>
              <input
                type="password"
                required
                value={confirmPassword}
                onChange={(e) => setConfirmPassword(e.target.value)}
                placeholder="••••••••"
                className={`w-full px-3 py-2.5 rounded-xl border text-xs outline-none ${inputBg}`}
              />
            </div>

            <button
              type="submit"
              disabled={loading}
              className="w-full sm:w-auto px-6 py-3 bg-[#3D5EF6] hover:bg-[#2E4FE0] text-white rounded-xl font-bold text-xs shadow-md transition cursor-pointer disabled:opacity-50"
            >
              {loading ? "Updating..." : "Update Credentials"}
            </button>
          </form>
        </div>

      </div>
    </div>
  );
}

"use client";
import toast from 'react-hot-toast';

import React, { useEffect, useState } from "react";
import { useTheme } from "@/providers/theme-provider";
import { agentAdminService } from "@/services/agent-admin.service";
import { 
  Search, FileText, Calendar, User, Compass, RefreshCw, ClipboardList, ShieldCheck, Info, X 
} from "lucide-react";

export default function ReferralsTracker() {
  const { theme , mounted} = useTheme();


  useEffect(() => {
    setMounted(true);
  }, []);

  const isDark = mounted ? theme === "dark" : true;

  const [activeTab, setActiveTab] = useState<"leads" | "purchases" | "conflicts">("leads");
  const [loading, setLoading] = useState(true);

  // Data states
  const [leads, setLeads] = useState<any[]>([]);
  const [seafarers, setSeafarers] = useState<any[]>([]);
  const [conflicts, setConflicts] = useState<any[]>([]);
  const [resolvingId, setResolvingId] = useState<string | null>(null);
  const [remarksMap, setRemarksMap] = useState<Record<string, string>>({});
  const [selectedLead, setSelectedLead] = useState<any | null>(null);

  // Filter states
  const [searchLeads, setSearchLeads] = useState("");
  const [statusFilter, setStatusFilter] = useState("all");
  const [searchPurchases, setSearchPurchases] = useState("");

  const card = `rounded-[16px] p-7 border-0 card-elevated transition-all duration-300 hover:-translate-y-0.5 ${
    isDark
      ? "bg-[#111827] text-white"
      : "bg-white text-[#111827]"
  }`;
  const labelText = isDark ? "text-white/50" : "text-[#6B7280]";
  const ht = isDark ? "text-white/80" : "text-[#111827]";
  const mt = isDark ? "text-white/35" : "text-[#9CA3AF]";
  const borderB = isDark ? "border-white/5" : "border-slate-100";

  const loadData = async () => {
    setLoading(true);
    try {
      const [leadsList, seafarersList, conflictsList] = await Promise.all([
        agentAdminService.getReferralLeads(),
        agentAdminService.getReferredSeafarers(),
        agentAdminService.getReferralConflicts()
      ]);
      setLeads(leadsList);
      setSeafarers(seafarersList);
      setConflicts(conflictsList);
    } catch (err) {
      console.error("Failed to load referral data: ", err);
    } finally {
      setLoading(false);
    }
  };

  const handleResolveConflict = async (purchaseId: string, approvedAgentId: string) => {
    const remarks = remarksMap[purchaseId] || "First valid registration matching seafarer.";
    setResolvingId(purchaseId);
    try {
      await agentAdminService.resolveConflict(purchaseId, approvedAgentId, remarks);
      toast.success("Referral dispute resolved successfully!");
      await loadData();
    } catch (err: any) {
      toast.error(err.response?.data?.message || err.message || "Failed to resolve conflict.");
    } finally {
      setResolvingId(null);
    }
  };

  useEffect(() => {
    let isSubscribed = true;
    (async () => {
      if (isSubscribed) {
        await loadData();
      }
    })();
    return () => { isSubscribed = false; };
  }, []);

  // Filter logic for Leads
  const filteredLeads = leads.filter(lead => {
    const matchesSearch = 
      lead.name?.toLowerCase().includes(searchLeads.toLowerCase()) ||
      lead.email?.toLowerCase().includes(searchLeads.toLowerCase()) ||
      lead.agentName?.toLowerCase().includes(searchLeads.toLowerCase());

    const matchesStatus = 
      statusFilter === "all" ||
      lead.status.toLowerCase() === statusFilter;

    return matchesSearch && matchesStatus;
  });

  // Filter logic for Purchases
  const filteredSeafarers = seafarers.filter(sf => {
    return (
      sf.seafarerName?.toLowerCase().includes(searchPurchases.toLowerCase()) ||
      sf.courseName?.toLowerCase().includes(searchPurchases.toLowerCase()) ||
      sf.agentName?.toLowerCase().includes(searchPurchases.toLowerCase())
    );
  });

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-4">
        <div>
          <h1 className={`text-2xl font-bold tracking-tight ${ht}`}>Referrals Tracker</h1>
          <p className={`text-xs mt-1.5 ${mt}`}>
            Monitor referral pipeline leads and course bookings referred by agents.
          </p>
        </div>
      </div>

      {/* Tabs */}
      <div className={`flex border-b ${borderB}`}>
        <button
          onClick={() => setActiveTab("leads")}
          className={`px-5 py-3 text-xs font-bold uppercase tracking-wider border-b-2 transition-all cursor-pointer ${
            activeTab === "leads"
              ? "border-[#3D5EF6] text-[#3D5EF6]"
              : "border-transparent text-slate-400 hover:text-slate-200"
          }`}
        >
          Referral Pipeline (Leads)
        </button>
        <button
          onClick={() => setActiveTab("purchases")}
          className={`px-5 py-3 text-xs font-bold uppercase tracking-wider border-b-2 transition-all cursor-pointer ${
            activeTab === "purchases"
              ? "border-[#3D5EF6] text-[#3D5EF6]"
              : "border-transparent text-slate-400 hover:text-slate-200"
          }`}
        >
          Referred Purchases (Bookings)
        </button>
        <button
          onClick={() => setActiveTab("conflicts")}
          className={`px-5 py-3 text-xs font-bold uppercase tracking-wider border-b-2 transition-all cursor-pointer ${
            activeTab === "conflicts"
              ? "border-[#3D5EF6] text-[#3D5EF6]"
              : "border-transparent text-slate-400 hover:text-slate-200"
          }`}
        >
          Conflicting Referrals (Manual Review)
        </button>
      </div>

      {activeTab === "leads" ? (
        <>
          {/* Leads Filters */}
          <div className="flex flex-col md:flex-row gap-4">
            <label className={`flex-1 flex items-center gap-2 px-3 py-2.5 rounded-xl border text-sm ${isDark ? "bg-white/5 border-white/10 text-white/60" : "bg-white border-slate-200 text-slate-600 shadow-sm"}`}>
              <Search className="w-4 h-4 opacity-55" />
              <input
                type="text"
                value={searchLeads}
                onChange={(e) => setSearchLeads(e.target.value)}
                placeholder="Search leads by name, email, or agent..."
                className="bg-transparent outline-none w-full text-xs"
              />
            </label>

            <div className="flex gap-2">
              <select
                value={statusFilter}
                onChange={(e) => setStatusFilter(e.target.value)}
                className={`px-3 py-2.5 rounded-xl border text-xs font-semibold outline-none cursor-pointer ${isDark ? "bg-white/5 border-white/10 text-white" : "bg-white border-[#E5E7EB] text-[#111827] shadow-sm"}`}
              >
                <option value="all">All Statuses</option>
                <option value="new">New Leads</option>
                <option value="contacted">Contacted</option>
                <option value="registered">Registered</option>
                <option value="converted">Converted</option>
                <option value="expired">Expired</option>
                <option value="cancelled">Cancelled</option>
              </select>

              <button 
                onClick={loadData}
                className={`p-2.5 rounded-xl border flex items-center justify-center cursor-pointer transition ${isDark ? "border-white/10 hover:bg-white/5 text-white/50" : "border-slate-200 hover:bg-slate-50 text-slate-500 shadow-sm"}`}
              >
                <RefreshCw className="w-4 h-4" />
              </button>
            </div>
          </div>

          {/* Leads Table */}
          <div className={card}>
            {loading ? (
              <div className="flex h-40 items-center justify-center">
                <div className="w-8 h-8 border-4 border-[#3D5EF6] border-t-transparent rounded-full animate-spin" />
              </div>
            ) : filteredLeads.length === 0 ? (
              <div className="text-center py-10">
                <p className={`text-xs ${mt}`}>No referral leads found.</p>
              </div>
            ) : (
              <div className="overflow-x-auto">
                <table className="w-full text-left text-xs border-collapse">
                  <thead>
                    <tr className={`border-b pb-3 ${isDark ? "border-white/5 text-white/30" : "border-slate-100 text-slate-400"} uppercase font-semibold tracking-wider`}>
                      <th className="py-3.5 px-2">Seafarer</th>
                      <th className="py-3.5 px-2">Referring Agent</th>
                      <th className="py-3.5 px-2">Course / Location</th>
                      <th className="py-3.5 px-2">Status</th>
                      <th className="py-3.5 px-2">Timeline</th>
                      <th className="py-3.5 px-2 text-right">Details</th>
                    </tr>
                  </thead>
                  <tbody className={isDark ? "divide-y divide-white/5" : "divide-y divide-slate-100"}>
                    {filteredLeads.map((lead) => (
                      <tr key={lead.id} className="hover:bg-white/[0.01] transition-all">
                        <td className="py-4 px-2">
                          <p className={`font-bold ${isDark ? "text-white/95" : "text-slate-800"}`}>{lead.name}</p>
                          <p className={`text-[10px] mt-0.5 ${labelText}`}>{lead.email}</p>
                          <p className={`text-[10px] mt-0.5 ${labelText}`}>{lead.phone}</p>
                        </td>
                        <td className="py-4 px-2">
                          <div className="flex items-center gap-1.5">
                            <User className="w-3.5 h-3.5 text-[#3D5EF6]" />
                            <span className="font-semibold">{lead.agentName}</span>
                          </div>
                        </td>
                        <td className="py-4 px-2">
                          <div className="flex items-center gap-1.5">
                            <Compass className="w-3.5 h-3.5 text-[#3D5EF6]" />
                            <span className="font-semibold">{lead.remarks ? lead.remarks.replace("Interested in ", "") : "STCW course"}</span>
                          </div>
                          {lead.city && <p className={`text-[10px] mt-0.5 ${labelText}`}>{lead.city}</p>}
                        </td>
                        <td className="py-4 px-2">
                          <span className={`px-2.5 py-1 rounded-full text-[10px] font-bold ${
                            lead.status === "Converted" 
                              ? "bg-emerald-500/10 text-emerald-500" 
                              : lead.status === "Expired" 
                              ? "bg-slate-500/10 text-slate-500" 
                              : lead.status === "Cancelled"
                              ? "bg-red-500/10 text-red-500"
                              : "bg-slate-100 dark:bg-white/5 text-slate-600 dark:text-slate-400 border border-slate-200 dark:border-white/10"
                          }`}>
                            {lead.status}
                          </span>
                        </td>
                        <td className="py-4 px-2">
                          <p className="flex items-center gap-1.5 text-[10px]">
                            <Calendar className="w-3 h-3 text-[#3D5EF6]" />
                            Created: {new Date(lead.createdAt).toLocaleDateString("en-IN", { day: 'numeric', month: 'short' })}
                          </p>
                          <p className={`flex items-center gap-1.5 text-[10px] mt-1 ${labelText}`}>
                            <Calendar className="w-3 h-3 text-[#3D5EF6]/50" />
                            Expires: {new Date(lead.expiryAt).toLocaleDateString("en-IN", { day: 'numeric', month: 'short' })}
                          </p>
                        </td>
                        {/* Details Action Button */}
                        <td className="py-4 px-2 text-right">
                          <button
                            onClick={() => setSelectedLead(lead)}
                            className={`p-1.5 rounded-xl border flex items-center justify-center transition-all duration-300 hover:scale-110 active:scale-95 shadow-sm cursor-pointer ml-auto ${
                              isDark 
                                ? "bg-white/[0.02] border-white/10 text-[#3D5EF6] hover:text-[#3D5EF6] hover:bg-[#3D5EF6]/10 hover:border-[#3D5EF6]/30" 
                                : "bg-slate-50 border-slate-200 text-[#3D5EF6] hover:text-[#2E4FE0] hover:bg-[#EEF1FE] hover:border-slate-300"
                            }`}
                            title="View Details"
                          >
                            <Info className="w-3.5 h-3.5" />
                          </button>
                        </td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            )}
          </div>
        </>
      ) : activeTab === "purchases" ? (
        <>
          {/* Purchases Filters */}
          <div className="flex flex-col md:flex-row gap-4">
            <label className={`flex-1 flex items-center gap-2 px-3 py-2.5 rounded-xl border text-sm ${isDark ? "bg-white/5 border-white/10 text-white/60" : "bg-white border-slate-200 text-slate-600 shadow-sm"}`}>
              <Search className="w-4 h-4 opacity-55" />
              <input
                type="text"
                value={searchPurchases}
                onChange={(e) => setSearchPurchases(e.target.value)}
                placeholder="Search by seafarer name, course, or agent..."
                className="bg-transparent outline-none w-full text-xs"
              />
            </label>

            <button 
              onClick={loadData}
              className={`p-2.5 rounded-xl border flex items-center justify-center cursor-pointer transition ${isDark ? "border-white/10 hover:bg-white/5 text-white/50" : "border-slate-200 hover:bg-slate-50 text-slate-500 shadow-sm"}`}
            >
              <RefreshCw className="w-4 h-4" />
            </button>
          </div>

          {/* Purchases Table */}
          <div className={card}>
            {loading ? (
              <div className="flex h-40 items-center justify-center">
                <div className="w-8 h-8 border-4 border-[#3D5EF6] border-t-transparent rounded-full animate-spin" />
              </div>
            ) : filteredSeafarers.length === 0 ? (
              <div className="text-center py-10">
                <p className={`text-xs ${mt}`}>No referred purchases found.</p>
              </div>
            ) : (
              <div className="overflow-x-auto">
                <table className="w-full text-left text-xs border-collapse">
                  <thead>
                    <tr className={`border-b pb-3 ${isDark ? "border-white/5 text-white/30" : "border-slate-100 text-slate-400"} uppercase font-semibold tracking-wider`}>
                      <th className="py-3.5 px-2">Seafarer Info</th>
                      <th className="py-3.5 px-2">Referring Agent</th>
                      <th className="py-3.5 px-2">Course Purchased</th>
                      <th className="py-3.5 px-2">Purchase Amount</th>
                      <th className="py-3.5 px-2">Purchase Date</th>
                      <th className="py-3.5 px-2 text-right">Referral Status</th>
                    </tr>
                  </thead>
                  <tbody className={isDark ? "divide-y divide-white/5" : "divide-y divide-slate-100"}>
                    {filteredSeafarers.map((sf) => (
                      <tr key={sf.id} className="hover:bg-white/[0.01] transition-all">
                        <td className="py-4 px-2">
                          <div className="flex items-center gap-1.5">
                            <User className="w-3.5 h-3.5 text-[#3D5EF6]" />
                            <span className="font-bold">{sf.seafarerName}</span>
                          </div>
                        </td>
                        <td className="py-4 px-2">
                          <p className={`font-semibold ${isDark ? "text-white/80" : "text-slate-700"}`}>{sf.agentName}</p>
                          <p className={`text-[10px] ${labelText}`}>{sf.agentEmail}</p>
                        </td>
                        <td className="py-4 px-2">
                          <span className="font-semibold">{sf.courseName}</span>
                        </td>
                        <td className="py-4 px-2 font-bold">
                          {sf.purchaseAmount}
                        </td>
                        <td className="py-4 px-2">
                          {new Date(sf.purchaseDate).toLocaleDateString("en-IN", { day: 'numeric', month: 'short', year: 'numeric' })}
                        </td>
                        <td className="py-4 px-2 text-right">
                          <span className={`px-2.5 py-1 rounded-full text-[10px] font-bold flex items-center gap-1.5 justify-end bg-emerald-500/10 text-emerald-500`}>
                            <ShieldCheck className="w-3.5 h-3.5" />
                            {sf.status}
                          </span>
                        </td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            )}
          </div>
        </>
      ) : (
        <>
          {/* Conflicts Panel (Manual Review) */}
          <div className="space-y-6">
            {conflicts.length === 0 ? (
              <div className={card}>
                <div className="text-center py-10">
                  <p className={`text-xs ${mt}`}>No conflicting referral disputes requiring manual review.</p>
                </div>
              </div>
            ) : (
              <div className="grid grid-cols-1 gap-6">
                {conflicts.map((conflict) => {
                  // Find the winner based on earliest leadSubmittedAt
                  let earliestAgentId = "";
                  let earliestTime = Infinity;
                  conflict.agents.forEach((ag: any) => {
                    const t = new Date(ag.leadSubmittedAt).getTime();
                    if (t < earliestTime) {
                      earliestTime = t;
                      earliestAgentId = ag.agentId;
                    }
                  });

                  return (
                    <div key={conflict.purchaseId} className={card}>
                      {/* Conflict Header */}
                      <div className="flex flex-col md:flex-row justify-between border-b pb-4 mb-4 border-white/5 gap-4">
                        <div>
                          <span className="px-2 py-0.5 rounded bg-red-500/10 text-red-500 font-extrabold text-[9px] uppercase tracking-wider animate-pulse">
                            ⚠️ Duplicate Lead Conflict
                          </span>
                          <h3 className="text-sm font-bold mt-2">Seafarer: {conflict.seafarerName}</h3>
                          <div className={`text-[10px] mt-1.5 space-y-1 ${labelText}`}>
                            <p>Email: <span className="font-semibold text-[#3D5EF6]">{conflict.seafarerEmail}</span></p>
                            <p>Phone: <span className="font-semibold text-[#3D5EF6]">{conflict.seafarerPhone}</span></p>
                            <p>INDOS Number: <span className="font-mono text-slate-700 dark:text-slate-300 font-bold">{conflict.indosNumber}</span></p>
                          </div>
                        </div>

                        <div className="md:text-right">
                          <p className="text-xs font-bold text-slate-400">Purchased Course</p>
                          <p className="text-xs font-black text-white mt-1">{conflict.courseName}</p>
                          <p className="text-xs font-black text-[#3D5EF6] mt-1">Fee: ₹{conflict.courseFee.toLocaleString("en-IN")}</p>
                          <p className={`text-[9px] mt-1.5 ${mt}`}>Purchase Date: {new Date(conflict.createdAt).toLocaleDateString("en-IN")}</p>
                        </div>
                      </div>

                      {/* Conflicting Agents list */}
                      <div className="space-y-4">
                        <p className="text-[10px] font-black uppercase tracking-wider text-slate-400">Conflicting Referral Claims</p>
                        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                          {conflict.agents.map((agent: any) => {
                            const isEarliest = agent.agentId === earliestAgentId;
                            return (
                              <div key={agent.agentId} className={`p-4 rounded-2xl border flex flex-col justify-between ${
                                isEarliest 
                                  ? (isDark ? "bg-[#3D5EF6]/5 border-[#3D5EF6]/20 text-white" : "bg-[#EEF1FE] border-slate-300 text-slate-900") 
                                  : (isDark ? "bg-white/5 border-white/10 text-white" : "bg-[#FAFAFA] border-[#E5E7EB] text-[#111827]")
                              }`}>
                                <div className="space-y-2">
                                  <div className="flex justify-between items-start gap-2">
                                    <div>
                                      <p className="font-bold text-xs flex items-center gap-1.5">
                                        <User className="w-3.5 h-3.5 text-[#3D5EF6]" />
                                        {agent.agentName}
                                      </p>
                                      <p className={`text-[10px] mt-0.5 ${labelText}`}>{agent.agentEmail}</p>
                                      <p className={`text-[10px] mt-0.5 ${labelText}`}>{agent.agentPhone}</p>
                                    </div>
                                    {isEarliest && (
                                      <span className="px-2 py-0.5 rounded-full bg-emerald-500/10 text-emerald-500 font-extrabold text-[9px] uppercase tracking-wider">
                                        🏆 Registered First
                                      </span>
                                    )}
                                  </div>

                                  <div className={`text-[10px] p-2 rounded-lg ${isDark ? "bg-slate-950/40 text-slate-350" : "bg-white text-slate-700"} space-y-1`}>
                                    <p className={labelText}>Lead Registered Time:</p>
                                    <p className="font-semibold">
                                      {new Date(agent.leadSubmittedAt).toLocaleString("en-IN", {
                                        day: "numeric",
                                        month: "short",
                                        year: "numeric",
                                        hour: "2-digit",
                                        minute: "2-digit"
                                      })}
                                    </p>
                                    <p className={`mt-1.5 ${labelText}`}>Commission Quote: <span className="font-bold text-emerald-500">₹{agent.commissionAmount.toLocaleString("en-IN")} ({agent.commissionRate}%)</span></p>
                                  </div>
                                </div>

                                <div className="mt-4 pt-3 border-t border-white/5">
                                  <button
                                    onClick={() => handleResolveConflict(conflict.purchaseId, agent.agentId)}
                                    disabled={resolvingId === conflict.purchaseId}
                                    className={`w-full py-2 rounded-xl font-bold text-[10px] uppercase tracking-wider shadow-sm transition ${
                                      resolvingId === conflict.purchaseId
                                        ? "bg-slate-700 text-slate-400 cursor-not-allowed"
                                        : "bg-[#3D5EF6] hover:bg-[#2E4FE0] text-white cursor-pointer"
                                    }`}
                                  >
                                    {resolvingId === conflict.purchaseId ? "Resolving..." : `Assign Commission to ${agent.agentName}`}
                                  </button>
                                </div>
                              </div>
                            );
                          })}
                        </div>

                        {/* Dispute Remarks */}
                        <div className="pt-2">
                          <label className="text-[10px] font-bold uppercase tracking-wider text-slate-400">Resolution Remarks *</label>
                          <textarea
                            placeholder="Add reason/remarks for the dispute resolution (e.g. First lead registered has authentic seafarer details)"
                            value={remarksMap[conflict.purchaseId] || ""}
                            onChange={(e) => setRemarksMap({ ...remarksMap, [conflict.purchaseId]: e.target.value })}
                            rows={2}
                            className={`w-full px-3 py-2 text-xs rounded-xl border outline-none mt-1.5 ${
                              isDark ? "bg-white/5 border-white/10 text-white placeholder-white/30" : "bg-[#FAFAFA] border-[#E5E7EB] text-[#111827] placeholder-[#9CA3AF]"
                            }`}
                          />
                        </div>
                      </div>
                    </div>
                  );
                })}
              </div>
            )}
          </div>
        </>
      )}
      {/* Referral Lead Details Modal */}
      {selectedLead && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/60 backdrop-blur-sm p-4 animate-in fade-in duration-200">
          <div className={`w-full max-w-lg p-6 rounded-[16px] card-elevated border-0 relative animate-in zoom-in-95 duration-200 ${
            isDark ? "bg-[#111827] text-white" : "bg-white text-[#111827]"
          }`}>
            <button
              onClick={() => setSelectedLead(null)}
              className={`absolute top-4 right-4 p-1.5 rounded-full transition ${isDark ? "hover:bg-white/5 text-white/40 hover:text-white" : "hover:bg-slate-100 text-slate-400 hover:text-slate-700"}`}
            >
              <X className="w-4 h-4" />
            </button>

            <h3 className="text-base font-bold mb-5 flex items-center gap-2 border-b pb-3 border-white/5">
              <ClipboardList className="w-4 h-4 text-[#3D5EF6]" />
              Referral Lead Details
            </h3>

            <div className="space-y-4 text-xs">
              <div className="grid grid-cols-3 gap-2 py-2 border-b border-white/5">
                <span className={labelText}>Full Name</span>
                <span className="col-span-2 font-bold">{selectedLead.name}</span>
              </div>
              <div className="grid grid-cols-3 gap-2 py-2 border-b border-white/5">
                <span className={labelText}>Email</span>
                <span className="col-span-2 font-semibold font-mono">{selectedLead.email}</span>
              </div>
              <div className="grid grid-cols-3 gap-2 py-2 border-b border-white/5">
                <span className={labelText}>Phone</span>
                <span className="col-span-2 font-semibold font-mono">{selectedLead.phone}</span>
              </div>
              <div className="grid grid-cols-3 gap-2 py-2 border-b border-white/5">
                <span className={labelText}>City / Location</span>
                <span className="col-span-2 font-semibold">{selectedLead.city || "Unknown"}</span>
              </div>
              <div className="grid grid-cols-3 gap-2 py-2 border-b border-white/5">
                <span className={labelText}>Referring Agent</span>
                <span className="col-span-2 font-bold">{selectedLead.agentName}</span>
              </div>
              <div className="grid grid-cols-3 gap-2 py-2 border-b border-white/5">
                <span className={labelText}>Interested Course</span>
                <span className="col-span-2 font-semibold">{selectedLead.remarks ? selectedLead.remarks.replace("Interested in ", "") : "STCW course"}</span>
              </div>
              <div className="grid grid-cols-3 gap-2 py-2 border-b border-white/5">
                <span className={labelText}>Status</span>
                <span className="col-span-2">
                  <span className={`px-2.5 py-0.5 rounded-full text-[10px] font-bold ${
                    selectedLead.status === "Converted" 
                      ? "bg-emerald-500/10 text-emerald-500" 
                      : selectedLead.status === "Expired" 
                      ? "bg-slate-500/10 text-slate-500" 
                      : selectedLead.status === "Cancelled"
                      ? "bg-red-500/10 text-red-500"
                      : "bg-slate-100 dark:bg-white/5 text-slate-600 dark:text-slate-400 border border-slate-200 dark:border-white/10"
                  }`}>
                    {selectedLead.status}
                  </span>
                </span>
              </div>
              <div className="grid grid-cols-3 gap-2 py-2 border-b border-white/5">
                <span className={labelText}>Timeline</span>
                <span className="col-span-2 font-semibold space-y-1 block">
                  <span className="block">Created: {new Date(selectedLead.createdAt).toLocaleString("en-IN", { day: 'numeric', month: 'short', year: 'numeric' })}</span>
                  <span className="block opacity-60">Expires: {new Date(selectedLead.expiryAt).toLocaleString("en-IN", { day: 'numeric', month: 'short', year: 'numeric' })}</span>
                </span>
              </div>
              <div className="pt-2">
                <span className={`${labelText} block mb-1.5`}>Dispute / Remarks</span>
                <div className={`p-4 rounded-xl leading-relaxed text-xs break-words ${isDark ? "bg-white/5 text-white/80 border border-white/5" : "bg-[#FAFAFA] text-[#111827] border border-[#E5E7EB]"}`}>
                  {selectedLead.remarks || "No remarks provided"}
                </div>
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

"use client";

import React, { useEffect, useState } from "react";
import { useTheme } from "@/providers/theme-provider";
import { agentAdminService } from "@/services/agent-admin.service";
import { BarChart3, RefreshCw, Sparkles, Users } from "lucide-react";
import {
  ResponsiveContainer, BarChart, Bar, XAxis, YAxis, Tooltip,
  PieChart, Pie, Cell
} from "recharts";

// Professional, readable chart palette — no neon/bright colors
const CHART_COLORS = ["#3D5EF6", "#0EA5E9", "#10B981", "#F59E0B", "#8B5CF6"];

export default function Reports() {
  const { theme , mounted} = useTheme();
  const isDark = theme === "dark";


  const [loading, setLoading] = useState(true);
  const [reportsData, setReportsData] = useState<any>(null);

  const [selectedAgentFilter, setSelectedAgentFilter] = useState("all");
  const [selectedRegionFilter, setSelectedRegionFilter] = useState("all");
  const [selectedMonthFilter, setSelectedMonthFilter] = useState("all");
  const [startDateFilter, setStartDateFilter] = useState("");
  const [endDateFilter, setEndDateFilter] = useState("");

  useEffect(() => {
    setMounted(true);
  }, []);

  const card = `rounded-[16px] p-6 border-0 card-elevated transition-all duration-300 ${
    isDark ? "bg-[#111827] text-white" : "bg-white text-[#111827]"
  }`;
  const labelText = isDark ? "text-white/50" : "text-[#6B7280]";
  const ht = isDark ? "text-white/95" : "text-[#111827]";
  const mt = isDark ? "text-white/35" : "text-[#9CA3AF]";

  const fetchReports = async (monthVal?: string) => {
    try {
      const monthToFetch = monthVal !== undefined ? monthVal : selectedMonthFilter;
      const data = await agentAdminService.getReports(monthToFetch);
      setReportsData(data);
    } catch (err) {
      console.error("Failed to load reports data:", err);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    let isSubscribed = true;
    (async () => {
      if (isSubscribed) {
        await fetchReports();
      }
    })();
    return () => { isSubscribed = false; };
  }, []);

  if (loading) {
    return (
      <div className="flex h-[60vh] items-center justify-center">
        <div className="w-8 h-8 border-4 border-[#3D5EF6] border-t-transparent rounded-full animate-spin" />
      </div>
    );
  }

  const defaultPerformance = [
    { agentName: "Kishan Manning Agency",  seafarers: 42, courses: 38, region: "Mumbai",  totalSales: "₹10,50,000", settledAmount: "₹8,40,000",  pendingBalance: "₹2,10,000", earnings: "₹1,26,000" },
    { agentName: "Oceanic Seamen Agency",  seafarers: 35, courses: 30, region: "Kochi",   totalSales: "₹8,75,000",  settledAmount: "₹7,00,000",  pendingBalance: "₹1,75,000", earnings: "₹1,05,000" },
    { agentName: "Maritime Crewing Corp",  seafarers: 28, courses: 24, region: "Chennai", totalSales: "₹7,00,000",  settledAmount: "₹5,60,000",  pendingBalance: "₹1,40,000", earnings: "₹84,000"   },
    { agentName: "Global Marine Services", seafarers: 15, courses: 10, region: "Kolkata", totalSales: "₹3,75,000",  settledAmount: "₹3,00,000",  pendingBalance: "₹75,000",   earnings: "₹45,000"   },
  ];

  const defaultRegionStats = [
    { name: "Mumbai",  value: 48 },
    { name: "Kochi",   value: 36 },
    { name: "Chennai", value: 28 },
    { name: "Kolkata", value: 18 },
    { name: "Goa",     value: 12 },
  ];

  const basePerformance = reportsData?.agentPerformance?.length > 0 ? reportsData.agentPerformance : defaultPerformance;
  const rawPerformance = basePerformance.map((p: any) => ({
    ...p,
    seafarers: Number(p.seafarers ?? p.conversions ?? p.leads ?? 0),
    courses: Number(p.courses ?? p.conversions ?? 0),
    region: p.region || (p.agentName?.includes("Kochi") || p.agentName?.includes("Oceanic") ? "Kochi" : p.agentName?.includes("Nautical") || p.agentName?.includes("Chennai") ? "Chennai" : p.agentName?.includes("SeaFarer") || p.agentName?.includes("Kolkata") ? "Kolkata" : "Mumbai"),
  }));
  const rawRegionStats = reportsData?.regionStats?.length > 0 ? reportsData.regionStats : defaultRegionStats;

  // Available months formatting helper
  const monthList: string[] = reportsData?.availableMonths?.length > 0
    ? reportsData.availableMonths
    : ["2026-09", "2026-08", "2026-07", "2026-06", "2026-05", "2026-04", "2026-03", "2026-02", "2026-01"];

  const monthOptions = monthList.map((m: string) => {
    const [year, month] = m.split("-");
    const dateObj = new Date(parseInt(year), parseInt(month) - 1, 1);
    const label = dateObj.toLocaleString("en-US", { month: "long", year: "numeric" });
    return { value: m, label };
  });

  // Get unique regions for the filter
  const availableRegions = Array.from(new Set([
    ...rawRegionStats.map((r: any) => r.name),
    ...rawPerformance.map((p: any) => p.region).filter(Boolean),
  ])).sort();

  // Apply filters
  const performance = rawPerformance.filter((p: any) => {
    const matchesAgent  = selectedAgentFilter === "all" || p.agentName === selectedAgentFilter;
    const matchesRegion = selectedRegionFilter === "all" || p.region === selectedRegionFilter;
    return matchesAgent && matchesRegion;
  });

  const filteredRegionStats = selectedRegionFilter === "all"
    ? rawRegionStats
    : rawRegionStats.filter((r: any) => r.name === selectedRegionFilter);

  // Summary metrics (no conversion rate)
  const totalSeafarersSum = performance.reduce((acc: number, p: any) => acc + Number(p.seafarers ?? 0), 0);
  const totalCoursesSum   = performance.reduce((acc: number, p: any) => acc + Number(p.courses ?? 0), 0);

  // Export to Excel
  const handleExportExcel = () => {
    if (performance.length === 0) {
      alert("No data available to export.");
      return;
    }
    const headers = ["Agent Name", "Region", "Total Seafarers", "Courses Booked", "Total Revenue", "Settled Amount", "Pending Balance", "Commission Earned"];
    const rows = performance.map((p: any) => [
      `"${p.agentName || ""}"`,
      `"${p.region || ""}"`,
      p.seafarers ?? 0,
      p.courses ?? 0,
      `"${p.totalSales || "₹0"}"`,
      `"${p.settledAmount || "₹0"}"`,
      `"${p.pendingBalance || "₹0"}"`,
      `"${p.earnings || "₹0"}"`,
    ]);
    const csvContent = "\uFEFF" + [headers.join(","), ...rows.map((r: (string | number)[]) => r.join(","))].join("\n");
    const blob = new Blob([csvContent], { type: "text/csv;charset=utf-8;" });
    const url  = URL.createObjectURL(blob);
    const link = document.createElement("a");
    link.setAttribute("href", url);
    link.setAttribute("download", `manning_agent_reports_${new Date().toISOString().substring(0, 10)}.csv`);
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
    URL.revokeObjectURL(url);
  };

  const tooltipStyle = {
    backgroundColor: isDark ? "#111827" : "#ffffff",
    borderColor:     isDark ? "#1F2937"  : "#E5E7EB",
    color:           isDark ? "#FAFAFA"  : "#111827",
    fontSize: "11px",
  };

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="flex items-center justify-between">
        <div>
          <h1 className={`text-2xl font-bold tracking-tight ${ht}`}>Operational Analytics</h1>
          <p className={`text-xs mt-1.5 ${mt}`}>Performance statistics and revenue reports by agent and region.</p>
        </div>
        <button
          onClick={() => fetchReports()}
          className={`p-2.5 rounded-xl border flex items-center justify-center cursor-pointer transition ${isDark ? "border-white/10 hover:bg-white/5 text-white/50" : "border-slate-200 hover:bg-slate-50 text-slate-500 shadow-sm"}`}
        >
          <RefreshCw className="w-4 h-4" />
        </button>
      </div>

      {/* Filters and Export Toolbar */}
      <div className={`p-4 rounded-lg border flex flex-col md:flex-row gap-4 items-end justify-between ${
        isDark ? "bg-[#111827] border-white/5" : "bg-[#FAFAFA] border-[#E5E7EB]"
      }`}>
        <div className="grid grid-cols-2 md:grid-cols-4 gap-3 w-full md:w-auto">
          {/* Manning Agent Filter */}
          <div className="space-y-1">
            <span className="text-[10px] font-bold text-slate-400 uppercase tracking-wider">Manning Agent</span>
            <select
              value={selectedAgentFilter}
              onChange={(e) => setSelectedAgentFilter(e.target.value)}
              className={`w-full px-3 py-2 rounded-xl border text-xs font-semibold outline-none cursor-pointer ${
                isDark ? "bg-white/5 border-white/10 text-white" : "bg-white border-[#E5E7EB] text-[#111827] shadow-sm"
              }`}
            >
              <option value="all">All Manning Agents</option>
              {rawPerformance.map((p: any, idx: number) => (
                <option key={idx} value={p.agentName}>{p.agentName}</option>
              ))}
            </select>
          </div>

          {/* Region Filter */}
          <div className="space-y-1">
            <span className="text-[10px] font-bold text-slate-400 uppercase tracking-wider">Region</span>
            <select
              value={selectedRegionFilter}
              onChange={(e) => setSelectedRegionFilter(e.target.value)}
              className={`w-full px-3 py-2 rounded-xl border text-xs font-semibold outline-none cursor-pointer ${
                isDark ? "bg-white/5 border-white/10 text-white" : "bg-white border-[#E5E7EB] text-[#111827] shadow-sm"
              }`}
            >
              <option value="all">All Regions</option>
              {availableRegions.map((region: string) => (
                <option key={region} value={region}>{region}</option>
              ))}
            </select>
          </div>

          {/* Start Date */}
          <div className="space-y-1">
            <span className="text-[10px] font-bold text-slate-400 uppercase tracking-wider">Start Date</span>
            <input
              type="date"
              value={startDateFilter}
              onChange={(e) => setStartDateFilter(e.target.value)}
              className={`w-full px-3 py-2 rounded-xl border text-xs outline-none ${
                isDark ? "bg-white/5 border-white/10 text-white" : "bg-white border-[#E5E7EB] text-[#111827]"
              }`}
            />
          </div>

          {/* End Date */}
          <div className="space-y-1">
            <span className="text-[10px] font-bold text-slate-400 uppercase tracking-wider">End Date</span>
            <input
              type="date"
              value={endDateFilter}
              onChange={(e) => setEndDateFilter(e.target.value)}
              className={`w-full px-3 py-2 rounded-xl border text-xs outline-none ${
                isDark ? "bg-white/5 border-white/10 text-white" : "bg-white border-[#E5E7EB] text-[#111827]"
              }`}
            />
          </div>
        </div>

        {/* Export */}
        <div className="flex gap-2 w-full md:w-auto shrink-0">
          <button
            onClick={handleExportExcel}
            className="flex-1 md:flex-none px-5 py-2.5 rounded-xl bg-emerald-600 hover:bg-emerald-500 text-white text-xs font-bold shadow-sm transition cursor-pointer"
          >
            Export Excel
          </button>
        </div>
      </div>

      {/* Summary Cards — 2 cards only (Conversion Rate removed) */}
      <div className="grid grid-cols-1 md:grid-cols-2 gap-5">
        <div className={card}>
          <div className="flex items-center justify-between">
            <span className={`text-[11px] font-semibold tracking-wider uppercase ${labelText}`}>Total Registered Seafarers</span>
            <Users className="w-4 h-4 text-[#3D5EF6]" />
          </div>
          <p className={`text-3xl font-bold mt-4 ${ht}`}>{totalSeafarersSum}</p>
          {selectedRegionFilter !== "all" && (
            <p className={`text-[10px] mt-1 ${mt}`}>Filtered by region: {selectedRegionFilter}</p>
          )}
        </div>

        <div className={card}>
          <div className="flex items-center justify-between">
            <span className={`text-[11px] font-semibold tracking-wider uppercase ${labelText}`}>Courses Booked</span>
            <Sparkles className="w-4 h-4 text-[#10B981]" />
          </div>
          <p className="text-3xl font-bold mt-4 text-[#10B981]">{totalCoursesSum}</p>
          {selectedAgentFilter !== "all" && (
            <p className={`text-[10px] mt-1 ${mt}`}>Filtered by agent: {selectedAgentFilter}</p>
          )}
        </div>
      </div>

      {/* Charts Grid — Top Referring (LARGE) vs Region-Wise (SMALLER) */}
      <div className="grid grid-cols-1 lg:grid-cols-12 gap-6 no-print">

        {/* Top Referring Agents — LARGE graph */}
        <div className={`lg:col-span-7 ${card}`}>
          <div className={`flex items-center justify-between border-b pb-3 mb-4 ${isDark ? "border-white/5" : "border-slate-100"}`}>
            <div className="flex items-center gap-2">
              <BarChart3 className="w-5 h-5 text-[#3D5EF6]" />
              <h3 className="text-base font-bold">Top Referring Manning Agents</h3>
            </div>
            {/* Month Filter Dropdown */}
            <div className="flex items-center gap-2">
              <span className="text-xs font-semibold text-slate-400">Month:</span>
              <select
                value={selectedMonthFilter}
                onChange={(e) => {
                  setSelectedMonthFilter(e.target.value);
                  fetchReports(e.target.value);
                }}
                className={`px-2.5 py-1.5 rounded-xl border text-xs font-bold outline-none cursor-pointer ${
                  isDark ? "bg-white/5 border-white/10 text-white" : "bg-white border-[#E5E7EB] text-[#111827] shadow-sm"
                }`}
              >
                <option value="all">All Months</option>
                {monthOptions.map((opt) => (
                  <option key={opt.value} value={opt.value}>
                    {opt.label}
                  </option>
                ))}
              </select>
            </div>
          </div>
          {/* Prominent, large chart height */}
          <div className="h-80 w-full text-xs">
            {mounted && (
              <ResponsiveContainer width="100%" height="100%">
                <BarChart data={performance} margin={{ top: 15, right: 15, left: -15, bottom: 40 }}>
                  <XAxis
                    dataKey="agentName"
                    tickLine={false}
                    axisLine={{ stroke: isDark ? "#334155" : "#e2e8f0" }}
                    interval={0}
                    tick={({ x, y, payload }) => {
                      const text = payload.value || "";
                      const words = text.split(" ");
                      let lines: string[] = [];
                      if (words.length > 2) {
                        const mid = Math.ceil(words.length / 2);
                        lines = [words.slice(0, mid).join(" "), words.slice(mid).join(" ")];
                      } else if (words.length === 2 && text.length > 12) {
                        lines = [words[0], words[1]];
                      } else {
                        lines = [text];
                      }

                      return (
                        <g transform={`translate(${x},${y})`}>
                          {lines.map((line, index) => (
                            <text
                              key={index}
                              x={0}
                              y={index * 12}
                              dy={12}
                              textAnchor="middle"
                              fill={isDark ? "#cbd5e1" : "#111827"}
                              fontSize={10}
                              fontWeight={700}
                            >
                              {line}
                            </text>
                          ))}
                        </g>
                      );
                    }}
                  />
                  <YAxis
                    stroke={isDark ? "#cbd5e1" : "#475569"}
                    fontSize={10}
                    fontWeight={600}
                    tickLine={false}
                  />
                  <Tooltip contentStyle={tooltipStyle} />
                  <Bar
                    dataKey="seafarers"
                    name="Total Seafarers"
                    fill="#3D5EF6"
                    barSize={36}
                    radius={[6, 6, 0, 0]}
                    isAnimationActive={false}
                  />
                </BarChart>
              </ResponsiveContainer>
            )}
          </div>
        </div>

        {/* Region-Wise Seafarers — SMALLER graph */}
        <div className={`lg:col-span-5 ${card}`}>
          <div className={`flex items-center gap-2 border-b pb-3 mb-4 ${isDark ? "border-white/5" : "border-slate-100"}`}>
            <BarChart3 className="w-4 h-4 text-[#3D5EF6]" />
            <h3 className="text-sm font-bold">
              Region-Wise Seafarers
              {selectedRegionFilter !== "all" && (
                <span className="ml-2 text-[10px] font-semibold text-[#3D5EF6] bg-[#3D5EF6]/10 px-2 py-0.5 rounded">
                  {selectedRegionFilter}
                </span>
              )}
            </h3>
          </div>

          {filteredRegionStats.length === 0 ? (
            <p className={`text-xs py-12 text-center ${mt}`}>No regional data for selected filter.</p>
          ) : (
            <div className="flex flex-col items-center gap-4">
              {/* Compact donut */}
              <div className="w-full h-48 shrink-0">
                {mounted && (
                  <ResponsiveContainer width="100%" height="100%">
                    <PieChart>
                      <Pie
                        data={filteredRegionStats}
                        cx="50%"
                        cy="50%"
                        innerRadius={45}
                        outerRadius={70}
                        paddingAngle={4}
                        dataKey="value"
                        isAnimationActive={false}
                      >
                        {filteredRegionStats.map((entry: any, index: number) => (
                          <Cell key={`cell-${index}`} fill={CHART_COLORS[index % CHART_COLORS.length]} />
                        ))}
                      </Pie>
                      <Tooltip contentStyle={tooltipStyle} />
                      <text x="50%" y="44%" textAnchor="middle" dominantBaseline="middle" fill={isDark ? "#fff" : "#111827"} fontSize="16" fontWeight="800">
                        {filteredRegionStats.reduce((sum: number, item: any) => sum + item.value, 0)}
                      </text>
                      <text x="50%" y="62%" textAnchor="middle" dominantBaseline="middle" fill="#94a3b8" fontSize="8" fontWeight="700" letterSpacing="1">
                        SEAFARERS
                      </text>
                    </PieChart>
                  </ResponsiveContainer>
                )}
              </div>

              {/* Legend grid */}
              <div className="w-full grid grid-cols-2 gap-2 text-xs pt-2 border-t border-slate-100 dark:border-white/5">
                {(() => {
                  const total = filteredRegionStats.reduce((sum: number, item: any) => sum + item.value, 0);
                  return filteredRegionStats.map((entry: any, index: number) => {
                    const pct = total > 0 ? Math.round((entry.value / total) * 100) : 0;
                    return (
                      <div key={entry.name} className="flex items-center justify-between gap-1 text-[11px]">
                        <div className="flex items-center gap-1.5 min-w-0">
                          <span className="w-2 h-2 rounded-full shrink-0" style={{ backgroundColor: CHART_COLORS[index % CHART_COLORS.length] }} />
                          <span className={`font-semibold truncate ${ht}`}>{entry.name}</span>
                        </div>
                        <span className={`font-bold shrink-0 ${ht}`}>{entry.value} ({pct}%)</span>
                      </div>
                    );
                  });
                })()}
              </div>
            </div>
          )}
        </div>
      </div>

      {/* Agent Performance Table */}
      <div className={card}>
        <div className={`flex items-center gap-2 border-b pb-3 mb-4 ${isDark ? "border-white/5" : "border-slate-100"}`}>
