import {
  Files, Upload, Download, CheckCircle2, AlertCircle, Clock, ShieldAlert,
  Sparkles, CloudLightning, Eye, X, ChevronUp, ChevronDown, FileText
} from "lucide-react";

interface DocumentMeta {
