  type: string;
  label: string;
  status: string;
  expiryDate: string | null;
  uploadedAt: string | null;
  url: string | null;
  documentNumber?: string | null;
  placeOfIssue?: string | null;
  dateOfIssue?: string | null;
  remarks?: string | null;
}

interface UploadState {
  type: string;
  progress?: number;
  loading: boolean;
  file?: File | null;
  expiryDate?: string;
  documentNumber?: string;
  placeOfIssue?: string;
  dateOfIssue?: string;
  error?: string;
  success?: string;
