} from "lucide-react";

export default function OnboardingPage() {
  const { theme , mounted} = useTheme();

  React.useEffect(() => {
    setMounted(true);
  }, []);
  const isDark = mounted ? theme === "dark" : true;
  const router = useRouter();

  const [step, setStep] = useState(1);
