    setErrorMsg("");
    if (!termsAgreed) {
      setErrorMsg("You must accept the Terms & Conditions to complete your onboarding registration.");
      return;
    }
    setLoading(true);
    try {
      // 1. Submit Onboarding Data to Backend
      await agentService.onboard({
        agencyName: profile.agencyName,
        phone: profile.phone,
      });
