    mobile: '',
    dob: '',
    nationality: '',
    gender: '',
    cdcNumber: '',
    passportNumber: '',
    indosNumber: '',
    course: '',
    amount: '',
    paymentMethod: '',
    paymentStatus: 'Paid',
  });

