      setPhone("");
      setDob("");
      setNationality("");
      setGender("");
      setCdcNo("");
      setPassportNo("");
      setIndosNo("");
      setPassportFile(null);
      setPhotoFile(null);
      setCdcFile(null);
      setOtherDocsFile(null);
      setValidationError(null);
