                </th>
                <th onClick={() => handleSort("rank")} className="py-3 px-4 cursor-pointer hover:text-sky-400 transition-colors">
                  <div className="flex items-center gap-1.5">
                    Rank & Dept
                    <ArrowUpDown className="w-3 h-3 opacity-60" />
