        };
      case "rejected":
        return {
          label: "Rejected",
          textColor: isDark ? "text-rose-400" : "text-rose-600",
        };
      case "missing":
      default:
        return {
          label: "Document Not Uploaded",
          textColor: isDark ? "text-slate-400" : "text-slate-500",
        };
    }
  };

