                  isDark 
                    ? "bg-gradient-to-r from-cyan-500 to-blue-600 text-white hover:shadow-cyan-500/20 hover:brightness-110" 
                    : "bg-[#3b71cb] text-white hover:bg-[#2c5fb3]"
