                            <span className="text-[9px] text-slate-500">({course.ratingCount || "100"}+ reviews)</span>
                          </div>
                          <div className="flex items-center gap-1 font-bold text-[10px] uppercase tracking-wider text-slate-500">
                            <Clock className="w-3.5 h-3.5" />
