                          </Link>
                        </div>
                      </div>
                    </div>

                  </div>
                </ScrollReveal>
              ))}
            </div>

          </div>

        </div>
      </section>

      {/* Mobile Drawer Filter Panel (Overlayed) */}
      {mobileFiltersOpen && (
